#nullable enable
using System;using System.Linq;using System.Collections.Generic;using Core.Utils;using Core.DataRepository;using Il2CppInterop.Runtime;using Il2CppInterop.Runtime.InteropTypes;using Il2CppInterop.Runtime.InteropTypes.Arrays;using Game.GameModes;using Game.SceneManagement;using Game.GlobalMap;using Game.Matchmaking;using Game.ItemsSystem;using Game.ItemsSystem.ItemComponents;using Game.ExitZoneSystem.ItemComponents;using Game.SpawnPointSystem.BotSpawnPoints.Data;using Game.DroppedItemSpawnPointSystem.Data;using Game.DroppedItemSpawnPointSystem.Data.ItemAtSpawnPoints;using UnityEngine;
namespace Frontier.Reserve;
internal static class Repositories {
 static readonly System.Collections.Concurrent.ConcurrentQueue<(ILoadableRepository Repo,NativeRoot Root)> incoming=new();internal static void Enqueue(ILoadableRepository repo){if(repo!=null)incoming.Enqueue((repo,new NativeRoot(repo)));}internal static void Drain(){while(incoming.TryDequeue(out var r)){try{Capture(r.Repo);}catch(Exception e){Trace.Error("repository binding",e);}finally{r.Root.Dispose();}}}
 static readonly List<ILoadableRepository> captured=new();static readonly LeaseBag roots=new();
 static readonly List<MapSettingsDataRepository> maps=new();static readonly List<MatchmakingMapSettingsDataRepository> queues=new();static readonly List<BotSpawnPointDataRepository> botPoints=new();static readonly List<ItemSpawnPointDataRepository> lootPoints=new();
 static readonly List<ItemTemplatesRepository> templates=new();static readonly List<BotPresetDataRepository> bots=new();
 static readonly HashSet<IntPtr> seen=new(),sceneManagers=new();internal static UniqueId CrateId,ExitTemplate;internal static bool Ready{get;private set;}
 internal static string Reason{get;private set;}="Загрузка данных…";static double next;internal static MapSettingsData? LastMap;
 internal const long NameKey=3465000000000012200L,DescKey=3465000000000012201L;
 static Game.Common.LocalizedReference Text(long key)=>new(){TableReference="Items",TableEntryReference=key};
 internal static void Capture(ILoadableRepository r){if(r==null||r.WasCollected)return;if(!seen.Add(r.Pointer))return;roots.Keep(r);captured.Add(r);string p=r.FilePath.Replace('\\','/').Split('/').Last();
 switch(p){case "maps_settings.json":if(r.TryCast<MapSettingsDataRepository>() is {} m){maps.Add(m);AddMap(m);}break;case "matchmaking_map_settings.json":if(r.TryCast<MatchmakingMapSettingsDataRepository>() is {} q){queues.Add(q);AddQueue(q);}break;case "bot_spawn_points.json":if(r.TryCast<BotSpawnPointDataRepository>() is {} b)botPoints.Add(b);break;case "item_spawn_points.json":if(r.TryCast<ItemSpawnPointDataRepository>() is {} l)lootPoints.Add(l);break;case "item_templates.json":if(r.TryCast<ItemTemplatesRepository>() is {} t)templates.Add(t);break;case "bot_presets.json":if(r.TryCast<BotPresetDataRepository>() is {} p2)bots.Add(p2);break;}
 next=0;Ready=false;}
 internal static void Register(GlobalMapManager manager){var repo=manager._mapSettingsDataRepository?.TryCast<MapSettingsDataRepository>();if(repo!=null){if(!maps.Any(x=>x.Pointer==repo.Pointer)){roots.Keep(repo);maps.Add(repo);}AddMap(repo);}RegisterScene(manager._sceneManager);Ensure();}
 internal static void RegisterScene(Game.SceneManagement.SceneManager? manager){if(manager==null||manager.WasCollected)return;var container=manager._sceneDescriptionsContainer;if(container==null)return;var existing=container.Find(Identity.Map);if(existing!=null){if(existing.Id!=Identity.MapId)throw new InvalidOperationException("Reserve scene identity collision");return;}
 var d=ScriptableObject.CreateInstance<SceneDescription>();d._id=Identity.MapId;d._name=Identity.Map;d._type=SceneType.Map;d.name="Frontier Reserve";d._mainScene=new SceneDescription.SceneLoadingData{Name=Identity.Map,LoadingSourceType=SceneDescription.LoadingSourceType.InBuild,LoadingMode=SceneDescription.LoadingMode.Single,IsServerOnly=false};d._additionalScenes=new Il2CppReferenceArray<SceneDescription.SceneLoadingData>(0);d._settingOverrides=new Il2CppSystem.Collections.Generic.List<Core.Settings.ISettings>();roots.Keep(d);container._descriptions.Add(d);sceneManagers.Add(manager.Pointer);Trace.Add("sceneDescriptionsRegistered");}
 internal static bool Ensure(){if(Time.realtimeSinceStartupAsDouble<next)return Ready;next=Time.realtimeSinceStartupAsDouble+1;try{
 foreach(var m in maps)AddMap(m);foreach(var q in queues)AddQueue(q);
 if(maps.Count==0||queues.Count==0||templates.Count==0||bots.Count==0||botPoints.Count==0||lootPoints.Count==0){Reason="Загрузка данных…";return false;}
 if(!ResolveTemplates())return false;
 foreach(var b in bots)foreach(var id in BotIds){if(!b.TryGetData(id,out var data)||data==null){Reason="Не найден комплект охраны";return false;}}
 foreach(var repo in botPoints)AddBots(repo);foreach(var repo in lootPoints)AddLoot(repo);
 Ready=true;Reason="";if(!Loader.Failed&&!Loader.InProgress&&WorldBridge.ActiveCount==0)Trace.Data["status"]="READY_FOR_DEPLOYMENT";Trace.Data["templateBindings"]=new{crate=CrateId.ToString(),exit=ExitTemplate.ToString(),botPresets=BotIds.Select(i=>i.ToString()).ToArray(),lootPoints=Content.Map.Anchors.Count(a=>a.Kind=="loot"),enemyPoints=Content.Map.Anchors.Count(a=>a.Kind=="enemy")};Trace.Save();return true;
 }catch(Exception e){Ready=false;Reason="Ошибка подготовки локации";Trace.Error("content bindings",e);return false;}}
 // Existing grounded ground-bot recipes observed in the owner's installed native logs.
 internal static readonly UniqueId[] BotIds={UniqueId.Parse("fbd53f2f-9259-4bb4-aa42-5de9e8a4350c"),UniqueId.Parse("55b50950-77c2-4ed9-8568-d1685c68aece"),UniqueId.Parse("8877183c-ba1f-411a-9b75-87fda366ad46")};
 static T? Component<T>(Item item) where T:Il2CppObjectBase=>item.GetComponent(Il2CppType.Of<T>())?.TryCast<T>();
 static bool ResolveTemplates(){if(CrateId!=UniqueId.Empty&&ExitTemplate!=UniqueId.Empty){foreach(var repo in templates){if(!repo.TryGetData(CrateId,out var c)||c==null||!repo.TryGetData(ExitTemplate,out var e)||e==null)throw new InvalidOperationException("Client/server template bindings differ");}return true;}
 var t=templates[0];var all=t.GetAllData();int n=Identity.Count(all);if(n==0){Reason="Загрузка предметов…";return false;}var crates=new List<Item>();var exits=new List<Item>();
 for(int i=0;i<n;i++){var x=all[i];if(x==null)continue;var b=Component<BaseComponent>(x);if(b==null)continue;
 if(Component<ExitZoneComponent>(x) is {} e&&e.TimeToExit>0&&e.TimeToExit<=60)exits.Add(x);
 if(Component<SimpleContainerComponent>(x)!=null&&Component<IsPickableComponent>(x)==null&&(Component<LockComponent>(x)==null||Component<LockComponent>(x)!._data.IsOpenByDefault)&&Component<Game.InteractionSystem.ItemComponents.InteractableComponent>(x)!=null&&!string.IsNullOrWhiteSpace(b.VisualName)){
 string v=b.VisualName.ToLowerInvariant();if(v.Contains("box")||v.Contains("crate")||v.Contains("case")||v.Contains("container"))crates.Add(x);}}
 if(crates.Count==0||exits.Count==0){Reason="Не найдены игровые контейнеры или выходы";Trace.Data["bindingCandidates"]=new{crates=crates.Count,exits=exits.Count};return false;}
 var crate=crates.OrderBy(x=>Component<BaseComponent>(x)!.VisualName.Length).ThenBy(x=>x.Id.ToString(),StringComparer.Ordinal).First();var exit=exits.OrderBy(x=>Math.Abs(Component<ExitZoneComponent>(x)!.TimeToExit-10)).ThenBy(x=>x.Id.ToString(),StringComparer.Ordinal).First();CrateId=crate.Id;ExitTemplate=exit.Id;Trace.Data["crateVisual"]=Component<BaseComponent>(crate)!.VisualName;Trace.Data["exitSeconds"]=Component<ExitZoneComponent>(exit)!.TimeToExit;return ResolveTemplates();}
 static void AddMap(MapSettingsDataRepository repo){if(repo.TryGetData(Identity.MapId,out var old)&&old!=null){if(old.MapName!=Identity.Map)throw new InvalidOperationException("Reserve map ID collision");LastMap=old;return;}
 if(!repo.TryGetDataByMapName("01_Warehouse",out var donor)||donor==null)return;var map=new MapSettingsData{MapId=Identity.MapId,MapName=Identity.Map,Type=MapSettingsData.MapType.None,MainTimePhaseDuration=1800,ExtraTimePhaseDuration=300,MaxExitZonesPerPlayer=2,ExitZonesAssignMode=MapSettingsData.ExitZoneAssignMode.Default,EquipmentReturn=donor.EquipmentReturn,ShowOnGlobalMap=false,NotAvailableToDeploy=false,UnlockRequirements=null,LocalizedName=Text(NameKey),LocalizedDescription=Text(DescKey),UnlockedShortText=Text(NameKey),LockedShortText=Text(NameKey),IconAtlasName=donor.IconAtlasName,IconSpriteName=donor.IconSpriteName,NavigationSystemConfiguration="Frontier.Reserve.Navigation",GlobalMapSettings=new MapSettingsData.GlobalMapSettingsData{LocalizedName=Text(NameKey),Position=new Vector3Data{X=0,Y=0,Z=0},IsAvailableOutOfDevelopmentMode=true,IsAvailableInDemonstrationMode=true,ShowOnlyInEditor=false},SpawnPointOverrides=new Il2CppSystem.Collections.Generic.List<MapSettingsData.SpawnPointPresetData>(),ExitZoneOverrides=new Il2CppSystem.Collections.Generic.List<MapSettingsData.ExitZonePresetData>(),Scripts=new Il2CppSystem.Collections.Generic.List<MapSettingsData.MapScriptSettingsData>()};
 var ids=new Il2CppSystem.Collections.Generic.List<int>();foreach(var a in Content.Map.Anchors.Where(a=>a.Kind=="exit"))ids.Add(Identity.Ordinal(a,Content.Map));map.ExitZoneOverrides.Add(new MapSettingsData.ExitZonePresetData{ExitZoneIds=ids,MaxActiveExitZonesCount=new Il2CppSystem.Nullable<int>(2),UnlockRequirement=null});
 var rows=repo.GetAllData();var list=new Il2CppSystem.Collections.Generic.List<MapSettingsData>();for(int i=0;i<Identity.Count(rows,256);i++)list.Add(rows[i]);list.Add(map);repo.SetLoadedData(list,Identity.Salt(repo._data?.Hash,"map"));LastMap=roots.Keep(map);Trace.Add("mapRepositoriesRegistered");}
 static void AddQueue(MatchmakingMapSettingsDataRepository repo){if(repo.TryGetData(Identity.Map,out var old)&&old!=null)return;if(!repo.TryGetData("01_Warehouse",out var d)||d==null)return;var row=new MatchmakingMapSettingsData{MapName=Identity.Map,NonBotPlayersCounts=d.NonBotPlayersCounts,WaitDurations=d.WaitDurations};var rows=repo.GetAllData();var list=new Il2CppSystem.Collections.Generic.List<MatchmakingMapSettingsData>();for(int i=0;i<Identity.Count(rows,256);i++)list.Add(rows[i]);list.Add(row);repo.SetLoadedData(list,Identity.Salt(repo._data?.Hash,"queue"));roots.Keep(row);Trace.Add("queueRepositoriesRegistered");}
 static void AddBots(BotSpawnPointDataRepository repo){var anchors=Content.Map.Anchors.Where(a=>a.Kind=="enemy").ToArray();if(repo.TryGetData(Identity.Id(anchors[0].Id),out var old)&&old!=null)return;var rows=repo.GetAllData();var list=new Il2CppSystem.Collections.Generic.List<BotSpawnPointData>();for(int i=0;i<Identity.Count(rows);i++)list.Add(rows[i]);for(int i=0;i<anchors.Length;i++){var b=new BotSpawnPointData{Id=Identity.Id(anchors[i].Id),LeveledEquipments=new Il2CppSystem.Collections.Generic.List<BotSpawnPointData.LeveledEquipment>()};b.LeveledEquipments.Add(new BotSpawnPointData.LeveledEquipment{BotPresetId=BotIds[i%BotIds.Length],UnlockRequirement=null});list.Add(b);}repo.SetLoadedData(list,Identity.Salt(repo._data?.Hash,"bots"));Trace.Add("botSpawnRepositoriesRegistered");}
 static void AddLoot(ItemSpawnPointDataRepository repo){var anchors=Content.Map.Anchors.Where(a=>a.Kind=="loot").ToArray();if(repo.TryGetData(Identity.Id(anchors[0].Id),out var old)&&old!=null)return;var rows=repo.GetAllData();var donors=new List<ItemSpawnPointData>();var list=new Il2CppSystem.Collections.Generic.List<ItemSpawnPointData>();for(int i=0;i<Identity.Count(rows);i++){var d=rows[i];list.Add(d);if(d!=null&&!d.Personal&&d.Chance>0&&d.Item!=null&&!(d.SpawnPointName??"").Contains("Tutorial",StringComparison.OrdinalIgnoreCase))donors.Add(d);}donors=donors.OrderBy(d=>d.SpawnPointId.ToString(),StringComparer.Ordinal).ToList();if(donors.Count==0)throw new InvalidOperationException("No native item spawn contents available");
 for(int i=0;i<anchors.Length;i++){var d=donors[(i*7)%donors.Count];list.Add(new ItemSpawnPointData{SpawnPointId=Identity.Id(anchors[i].Id),SpawnPointName="Reserve/"+anchors[i].Id,Chance=.85f,Personal=false,Item=d.Item});}repo.SetLoadedData(list,Identity.Salt(repo._data?.Hash,"loot"));Trace.Data["lootDonorPolicy"]="native non-personal spawn contents; original donor records retained";Trace.Add("lootRepositoriesRegistered");}
}
